n=0
for i=mn+1,mn,-2 do n=n+1 io.write(tostring(i)," ") end print("count",n)
-- step larger than range
n=0
for i=1,10,100 do n=n+1 io.write(tostring(i)," ") end print("count",n)
-- limit clamping with float limit beyond integer range
n=0
